from pathlib import Path
import json,subprocess,base64
p=Path(__file__).resolve().parent
scripts={f.name:f.read_text() for f in p.glob('*.ps1')}
s=r'''$ErrorActionPreference='Stop';$data=[Console]::In.ReadToEnd()|ConvertFrom-Json;$out=@();foreach($f in $data.PSObject.Properties){$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseInput($f.Value,[ref]$tokens,[ref]$errors);if($errors.Count){throw ('Syntax: '+$f.Name)};$count=0;foreach($a in $ast.FindAll({param($a) $a -is [Management.Automation.Language.CommandAst]},$true)){$n=$a.GetCommandName();if($n -in @('Start-VM','Stop-VM','Remove-VM','Set-VM','Set-VMSecurity','Set-VMComPort','Remove-VMNetworkAdapter','New-VHD','Get-VHD','Add-VMScsiController','Get-VMScsiController','Add-VMHardDiskDrive','Get-VMHardDiskDrive')){$cmd=Get-Command $n -ErrorAction Stop;foreach($arg in $a.CommandElements){if($arg -is [Management.Automation.Language.CommandParameterAst]){$p=$arg.ParameterName;if($p -eq 'EA'){$p='ErrorAction'};if(-not $cmd.Parameters.ContainsKey($p)){throw ($f.Name+': '+$n+' does not accept '+$p)}}};$count++}};$out+=@{file=$f.Name;syntax=$true;vmCommandsChecked=$count}};$out|ConvertTo-Json -Compress'''
r=subprocess.run(['ssh','-o','BatchMode=yes','-o','StrictHostKeyChecking=yes','-o','ConnectTimeout=6','minipc','powershell.exe -NoProfile -NonInteractive -EncodedCommand '+base64.b64encode(s.encode('utf-16le')).decode()],input=json.dumps(scripts),capture_output=True,text=True,timeout=25)
(p/'ast-check.json').write_text(r.stdout);(p/'ast-check.stderr').write_text(r.stderr);print(r.returncode);print(r.stdout)
